// ================= Toyosu Market (豊洲市場, opened 2018) =================
// Block 6, the fish intermediate-wholesale hall (水産仲卸売場棟, 5 floors — Tokyo Metropolitan Central Wholesale Market guide),
// on its OSM footprint: the long pale market hall with its louvred upper floors, truck berths along the ground floor, the
// visitor deck and the roof garden (屋上緑化広場) on top. _b is block 7, the fish wholesale hall (水産卸売場棟, 5 floors), from its
// OSM parts. Heights are estimates (the guide gives floors, not heights): 5 market floors ~6 m.
const TY_COL = {W:{c:'#e3e1da', m:1, fh:6.0, cw:4.0}, W2:{c:'#d4d3cc', m:0, lk:0.3}, LV:{c:'#b8bcbd', m:0, lk:0.25}, GL:{c:'#76848f', m:1, fh:6.0, cw:3.6},
  DK:'#3e444a', ROOF:'#a9aba6', GRN:'#7f9a5c', PATH:'#cfc8b8', TRK:'#5d4f40', RED:{c:'#a81010', glow:'#ff2a14', gk:2.0}};
LANDMARKS.tytoyosu = {zh:'丰洲市场', en:'Toyosu Market', cat:'new', r:205, h:32, lt:{m:0, c:'#fff2dc', k:0.35, e:0.7},
  build(){
    const g = new THREE.Group(), B = mkB(), C = TY_COL, R = D.toy.b.w629546000.r, F = obb(R);
    const H = 29;
    prism(B.p(C.W), R, -3, H, false);
    // floor slabs every 6 m, louvre bands on the upper floors, a glazed strip under each slab
    bands(B.p(C.W2), R, [5.6, 11.6, 17.6, 23.6], 0.9, 0.35);
    bands(B.p(C.LV), R, [12.6, 18.6, 24.6], 3.6, 0.2);
    bands(B.p(C.GL), R, [7.0], 3.8, 0.12);
    bands(B.p(C.W2), R, [H - 0.4], 1.6, 0.25);                // parapet
    // truck berths: dark openings along the two long sides at ground level
    for (const side of [-1, 1]){ for (let k = 0; k < 26; k++){ const s = -F.L/2 + 14 + k*(F.L - 28)/25;
      const x = F.cx + F.ux*s - F.uz*side*(F.W/2 + 0.2), z = F.cz + F.uz*s + F.ux*side*(F.W/2 + 0.2);
      if (!pip(offsetP(R, 3), x, z)) continue; obox(B.p(C.DK), x, z, F.ux, F.uz, 3.2, 0.3, 0.2, 4.8); } }
    // roof: the roof garden (lawn, paths, trees) over most of it, plant houses and the visitor deck along one long side
    const top = offsetP(R, -1.5); prism(B.p(C.ROOF), top, H - 0.4, H, true);
    // the roof garden covers the end third of the roof (the rest: plant decks and skylight rows)
    const LS = -F.L/2 + F.L/6 + 4, LQ = [[-1, -1], [1, -1], [1, 1], [-1, 1]].map(([p, q]) => { const ss = LS + p*(F.L/6 - 12), bb = q*(F.W/2 - 16); return [F.cx + F.ux*ss - F.uz*bb, F.cz + F.uz*ss + F.ux*bb]; }), lawn = LQ;
    prism(B.p(C.GRN), lawn, H, H + 0.25, true);
    for (let k = 0; k < 9; k++){ const s = F.L/6 + 10 + k*((F.L/2 - 30) - (F.L/6 + 10))/8, x = F.cx + F.ux*s, z = F.cz + F.uz*s; obox(B.p(C.LV), x, z, F.ux, F.uz, 2.2, F.W/2 - 20, H, H + 1.6); }
    const rng = LMCTX.rng;
    for (let k = 0; k < 3; k++){ const s = -F.L/2 + 30 + k*(F.L/3 - 50)/2, x = F.cx + F.ux*s, z = F.cz + F.uz*s; obox(B.p(C.PATH), x, z, F.ux, F.uz, 3, F.W/2 - 18, H + 0.25, H + 0.32); }
    for (let k = 0; k < 40; k++){ const s = LS + (rng() - 0.5)*(F.L/3 - 30), b = (rng() - 0.5)*(F.W - 40), x = F.cx + F.ux*s - F.uz*b, z = F.cz + F.uz*s + F.ux*b;
      if (pip(lawn, x, z)) ltree(B, x, H + 0.2, z, 0.8 + rng()*0.5, '#5f7f4a'); }
    for (let k = 0; k < 5; k++){ const s = -F.L/2 + 30 + k*(F.L - 60)/4, b = -F.W/2 + 9, x = F.cx + F.ux*s - F.uz*b, z = F.cz + F.uz*s + F.ux*b; obox(B.p(C.W2), x, z, F.ux, F.uz, 9, 4, H, H + 4.5); }
    rehostB(B, 'tytoyosu'); B.flush(g); return g;
  }};
SG_PLACES.push({type:'tytoyosu', lat:D.toy.ll[0], lon:D.toy.ll[1], rot:0});
